// Build the single-file bundle: server + embedded frontend (base64).
//   node scripts/build-bundle.mjs
// Output: bundle/mxbox.js (sqlite3 stays external — native module,
// installed by npm as a real dependency of the package)
import * as esbuild from "esbuild";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = path.join(path.dirname(fileURLToPath(import.meta.url)), "..");
const DIST = path.join(ROOT, "frontend", "dist");
const GENERATED = path.join(ROOT, "server", "src", "frontend-files.mjs");
const OUT = path.join(ROOT, "bundle");

if (!fs.existsSync(path.join(DIST, "index.html"))) {
  console.error("frontend/dist is not built — run: npm run build");
  process.exit(1);
}

// 1. Embed frontend/dist as base64 map
const files = {};
const walk = (dir, prefix = "") => {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const rel = `${prefix}/${entry.name}`;
    if (entry.isDirectory()) walk(path.join(dir, entry.name), rel);
    else files[rel] = fs.readFileSync(path.join(dir, entry.name)).toString("base64");
  }
};
walk(DIST);
fs.writeFileSync(
  GENERATED,
  `// GENERATED by scripts/build-bundle.mjs — do not edit\nexport const FILES = ${JSON.stringify(files)};\n`
);
console.log(`Embedded ${Object.keys(files).length} frontend files`);

// 2. Bundle server to a single ESM file
await esbuild.build({
  entryPoints: [path.join(ROOT, "server", "src", "server.mjs")],
  bundle: true,
  platform: "node",
  format: "esm",
  target: "node22",
  outfile: path.join(OUT, "mxbox.js"),
  // sqlite3 is a native module — keep it external so npm installs the prebuilt binary
  external: ["sqlite3"],
  banner: {
    js: 'import { createRequire } from "node:module"; const require = createRequire(import.meta.url);',
  },
});

const size = fs.statSync(path.join(OUT, "mxbox.js")).size;
console.log(`Bundle: bundle/mxbox.js (${(size / 1024).toFixed(0)} KB)`);
